var EXTRA=[{"dot": "gray", "j": "Arthroscopy Techniques", "h": "Sutura all-inside con nodo artroscopico per la bucket-handle del corno anteriore", "v": "Nota tecnica da Amman: un recupero artroscopico e un passafili evitano la mini-incisione dell'outside-in; il vantaggio sulla cute è un'affermazione degli autori, nessun esito clinico riportato.", "pmid": "42836072", "doi": "10.1002/atn2.70267", "temi": ["sutura meniscale", "bucket-handle", "tecnica chirurgica"]}, {"dot": "gray", "j": "Journal of Experimental Orthopaedics", "h": "Coni metafisari nella revisione settica di protesi: eradicazione alta, serie piccola", "v": "Serie retrospettiva senza controllo in due centri: l'infezione risulta eradicata nella grande maggioranza, ma le colture metafisarie positive nelle revisioni in un tempo restano un reperto esplorativo, non generalizzabile.", "pmid": "42836121", "doi": "10.1002/jeo2.70944", "temi": ["protesi totale", "revisione settica", "infezione"]}, {"dot": "gray", "j": "The Journal of Knee Surgery", "h": "Fibrillazione atriale e revisione dopo protesi totale: rischio maggiore in un database", "v": "Coorte retrospettiva su TriNetX con appaiamento per propensity: associazione con revisione e infezione periprotesica che gli autori stessi definiscono di effetto modesto, con i limiti del database.", "pmid": "42838115", "doi": "10.1055/a-2968-5946", "temi": ["protesi totale", "revisione", "comorbidità"]}, {"dot": "gray", "j": "Anaesthesia", "h": "IPACK o blocco tibiale selettivo dopo LCA: analgesia comparabile", "v": "RCT triplo cieco in anestesia generale con blocco del triangolo femorale: consumo di morfina e punteggi funzionali senza differenza significativa; l'abstract non permette di dire se la potenza bastasse a escludere differenze.", "pmid": "42838531", "doi": "10.1111/anae.70433", "temi": ["LCA", "analgesia", "blocco nervoso"]}, {"dot": "gray", "j": "Research in Health Services & Regions", "h": "Fisioterapia dopo LCA e menisco in Germania: l'esercizio terapeutico domina le prescrizioni", "v": "Sondaggio online a terapisti tedeschi, senza esiti clinici: dopo LCA le prescrizioni di esercizio superano i valori di riferimento del catalogo e le attese sono spesso lunghe; è un dato di pratica, non di efficacia.", "pmid": "42837055", "doi": "10.1007/s43999-026-00091-7", "temi": ["riabilitazione", "LCA", "menisco"]}, {"dot": "gray", "j": "Arthroplasty Today", "h": "Protesi nelle displasie scheletriche: esiti dopo screening multidisciplinare preoperatorio", "v": "Serie retrospettiva monocentrica (HSS) su pazienti con displasia scheletrica, con componenti su misura in circa metà dei casi: sopravvivenza e complicanze descritte per anca e ginocchio, senza gruppo di controllo.", "pmid": "42830780", "doi": "10.1016/j.artd.2026.102149", "temi": ["protesi totale", "displasia scheletrica", "revisione"]}, {"dot": "gray", "j": "Frontiers in Rehabilitation Sciences", "h": "Monitoraggio quantificato dell'esercizio di pompa della caviglia dopo protesi: RCT esplorativo", "v": "RCT esplorativo in aperto, con sensore indossabile e applicazione dopo protesi d'anca o di ginocchio: l'aderenza all'esercizio risulta più alta con il monitoraggio, ma il disegno è monocentrico ed esplorativo.", "pmid": "42835374", "doi": "10.3389/fresc.2026.1933740", "temi": ["protesi totale", "riabilitazione", "trombosi venosa"]}, {"dot": "gray", "j": "Knee Surgery, Sports Traumatology, Arthroscopy", "h": "Commento sulla TKA con realtà aumentata: limiti legamentosi invece che di allineamento", "v": "Commento senza abstract disponibile: oltre al titolo il contenuto non è verificato.", "pmid": "42831866", "doi": "10.1002/ksa.70611", "temi": ["protesi totale", "navigazione", "realtà aumentata"]}, {"dot": "gray", "j": "Musculoskeletal Surgery", "h": "Lettera sulla TKA robotica: durata dell'intervento ed eventi avversi in un ospedale pubblico", "v": "Lettera di commento a una coorte retrospettiva in un ospedale pubblico secondario; senza abstract, la critica sollevata non è verificabile oltre al titolo.", "pmid": "42834309", "doi": "10.1007/s12306-026-00985-2", "temi": ["protesi robotica", "TKA", "lettera"]}];
var SCOPERTE=[{"t": "Un modello di segmentazione 3D misura gli osteofiti alla TC prima della protesi robotica", "v": "Un gruppo coreano (J Robot Surg) ha addestrato una U-Net su 387 TC e la valuta su due coorti esterne da 100 ginocchia: Dice mediano 0,913 e 0,909, ICC dei volumi 0,977 e 0,972; su 66 TKA robotiche il volume stimato concorda con quello degli osteofiti resecati e misurati per spostamento d'acqua (ICC 0,876; limiti di concordanza 95% da -2,785 a +3,586 cc). Vale la deviazione perché porta l'intelligenza artificiale nella pianificazione che precede una TKA robotica; il riferimento intraoperatorio riguarda solo gli osteofiti accessibili, il robot usato non è riportato nell'abstract e il metodo è presentato come strumento di ricerca.", "pmid": "42837082", "doi": "10.1007/s11701-026-04015-y", "temi": ["intelligenza artificiale", "protesi robotica", "TC"]}, {"t": "Assistenti digitali con IA generativa: i pazienti di protesi li vogliono?", "v": "Sondaggio su 101 pazienti di protesi d'anca e di ginocchio in un solo istituto (Arthroplasty Today): contano più l'accuratezza dell'informazione e il rapporto con il curante che la rapidità; disponibilità a usare l'assistente e fiducia sono miste, e telefonare allo studio resta la scelta prevalente nei vari scenari postoperatori. Vale la deviazione perché dice dove l'IA non sostituisce la relazione; è un sondaggio in un solo centro, senza intervalli di confidenza nell'abstract.", "pmid": "42830754", "doi": "10.1016/j.artd.2026.102152", "temi": ["intelligenza artificiale", "protesi", "comunicazione col paziente"]}, {"t": "Cellule mesenchimali e PRP nell'artrosi: speranza, prove e clamore", "v": "Una prospettiva (Osteoarthritis Imaging, Hunter e Fan) separa ciò che le terapie rigenerative hanno dimostrato da ciò che le aspettative di pazienti, mercato e media hanno anticipato, e sostiene che serve cautela finché non arrivano studi di fase 3 ben disegnati. Vale la deviazione perché affronta dal lato dell'artrosi la stessa domanda posta ieri dalla meta-analisi sui biologici nel LCA; è un'opinione di esperti, non una sintesi quantitativa.", "pmid": "42838868", "doi": "10.1016/j.ostima.2026.100475", "temi": ["ortobiologici", "artrosi", "evidenza"]}];
var SOC={"1": {"video": "Quando il legamento crociato si rompe insieme al legamento sul lato interno, il ginocchio può ruotare in modo anomalo. Uno studio su 59 pazienti ha seguito per due anni una ricostruzione combinata.\n\nOltre al crociato è stato ricostruito il legamento collaterale mediale con un tendine della gamba. A due anni la stabilità era simile a quella del ginocchio sano, il test di rotazione era negativo nel 93% e due su tre erano tornati a qualche sport.\n\nIl limite: non c'è un gruppo di confronto e i punteggi di partenza sono stati ricostruiti a posteriori, quindi lo studio mostra che la tecnica è praticabile, non che prevalga su altre.\nFonte: PubMed, PMID 42836103.", "linkedin": "ACL + sMCL a banda singola con peroneo lungo diviso per AMRI (J Exp Orthop, ottobre 2026): coorte monocentrica, livello IV, 59/63 pazienti a 2 anni, tunnel-sparing.\n\nCassetto anteriore AMRI-correlato a 90° con rotazione esterna: differenza laterale 0,0 ± 1,3 mm (IC 95% da -0,4 a 0,3; margine di non inferiorità 3 mm); Lachman 1,8 ± 1,3 mm; pivot-shift negativo 93%; IKDC 59→85, Lysholm 61→89 (p<0,001); RTS 66%; AOFAS mediano 100; reinterventi 5/59 (8,5%).\n\nLimiti: nessun controllo, nessuna misura strumentale preoperatoria, PROM preoperatori retrospettivi, singolo operatore, coorte mista (30 primari, 26 revisioni, 7 re-revisioni); LCA con semitendineo nel 91% e LET nel 29%.\nFonte: PubMed, PMID 42836103.", "instagram": "Crociato e collaterale interno ricostruiti insieme.\n59 pazienti, due anni: ginocchio stabile quasi quanto l'altro.\nNessun gruppo di confronto.\nFonte: PubMed, PMID 42836103.", "pazienti": "A volte, insieme al legamento crociato, si danneggia anche il legamento sul lato interno del ginocchio.\n\nIn uno studio su 59 persone sono stati ricostruiti entrambi. Dopo due anni il ginocchio era stabile quasi come l'altro e circa due su tre erano tornati allo sport.\n\nLo studio non ha un gruppo di confronto: si discute con il chirurgo, caso per caso.\nFonte: PubMed, PMID 42836103."}};
var SOCV={"1": {"video": {"chir": ["Crociato e collaterale mediale nello stesso intervento: una coorte del Journal of Experimental Orthopaedics, ottobre 2026, segue 59 pazienti su 63 con instabilità rotatoria anteromediale, trattati con LCA più sMCL a banda singola con peroneo lungo diviso.", "A due anni la differenza laterale del cassetto anteriore in rotazione esterna è 0,0 ± 1,3 mm, IC 95% da -0,4 a 0,3; pivot-shift negativo nel 93%; IKDC da 59 a 85, Lysholm da 61 a 89; ritorno a qualsiasi sport 66%.", "Il limite: nessun gruppo di controllo, nessuna misura strumentale preoperatoria, punteggi di partenza raccolti a posteriori, un solo operatore. Un quadro di fattibilità, non di superiorità.\nFonte: PubMed, PMID 42836103."], "misto": ["Quando il legamento crociato si rompe insieme al legamento sul lato interno, il ginocchio può ruotare in modo anomalo. Uno studio su 59 pazienti ha seguito per due anni una ricostruzione combinata.", "Oltre al crociato è stato ricostruito il legamento collaterale mediale con un tendine della gamba. A due anni la stabilità era simile a quella del ginocchio sano, il test di rotazione era negativo nel 93% e due su tre erano tornati a qualche sport.", "Il limite: non c'è un gruppo di confronto e i punteggi di partenza sono stati ricostruiti a posteriori, quindi lo studio mostra che la tecnica è praticabile, non che prevalga su altre.\nFonte: PubMed, PMID 42836103."], "pazienti": ["A volte, insieme al legamento crociato, si danneggia anche il legamento sul lato interno del ginocchio.", "In uno studio su 59 persone sono stati ricostruiti entrambi. Dopo due anni il ginocchio era stabile quasi come l'altro e circa due su tre erano tornati allo sport.", "Lo studio non ha un gruppo di confronto: si discute con il chirurgo, caso per caso.\nFonte: PubMed, PMID 42836103."]}, "linkedin": {"chir": ["ACL + sMCL a banda singola con peroneo lungo diviso per AMRI (J Exp Orthop, ottobre 2026): coorte monocentrica, livello IV, 59/63 pazienti a 2 anni, tunnel-sparing.", "Cassetto anteriore AMRI-correlato a 90° con rotazione esterna: differenza laterale 0,0 ± 1,3 mm (IC 95% da -0,4 a 0,3; margine di non inferiorità 3 mm); Lachman 1,8 ± 1,3 mm; pivot-shift negativo 93%; IKDC 59→85, Lysholm 61→89 (p<0,001); RTS 66%; AOFAS mediano 100; reinterventi 5/59 (8,5%).", "Limiti: nessun controllo, nessuna misura strumentale preoperatoria, PROM preoperatori retrospettivi, singolo operatore, coorte mista (30 primari, 26 revisioni, 7 re-revisioni); LCA con semitendineo nel 91% e LET nel 29%.\nFonte: PubMed, PMID 42836103."], "misto": ["Crociato e collaterale mediale ricostruiti insieme per instabilità rotatoria anteromediale (J Exp Orthop, ottobre 2026): coorte di 59 pazienti seguita per due anni.", "Stabilità del cassetto in rotazione esterna senza differenza dal ginocchio sano (0,0 ± 1,3 mm), test di rotazione negativo nel 93%, IKDC da 59 a 85 e Lysholm da 61 a 89, ritorno a qualche sport nel 66%.", "Limite: nessun gruppo di confronto, punteggi di partenza raccolti a posteriori, casi di tipo diverso (primari e revisioni).\nFonte: PubMed, PMID 42836103."], "pazienti": ["Legamento crociato e legamento interno del ginocchio ricostruiti insieme: uno studio su 59 persone seguite per due anni.", "Il ginocchio operato era stabile quasi quanto l'altro e i punteggi riferiti erano più alti di prima; circa due su tre erano tornati allo sport.", "Studio senza gruppo di confronto: ogni caso si discute con il chirurgo.\nFonte: PubMed, PMID 42836103."]}, "instagram": {"chir": ["ACL + sMCL (peroneo lungo): 59 pazienti, 2 anni.", "Cassetto AMRI 0,0 ± 1,3 mm side-to-side; pivot-shift negativo 93%.", "Livello IV, nessun controllo.\nFonte: PubMed, PMID 42836103."], "misto": ["Crociato e collaterale interno ricostruiti insieme.", "59 pazienti, due anni: ginocchio stabile quasi quanto l'altro.", "Nessun gruppo di confronto.\nFonte: PubMed, PMID 42836103."], "pazienti": ["Due legamenti del ginocchio operati insieme.", "Dopo due anni, ginocchio stabile in 59 persone seguite.", "Studio senza confronto: se ne parla con il chirurgo.\nFonte: PubMed, PMID 42836103."]}, "reel": {"chir": ["ACL + sMCL: 59 pazienti.", "Cassetto 0,0 ± 1,3 mm.", "Livello IV, nessun controllo."], "misto": ["Crociato e collaterale insieme.", "Stabili a due anni.", "Senza gruppo di confronto."], "pazienti": ["Due legamenti, una sola operazione.", "Stabili dopo due anni.", "Si discute con il chirurgo."]}}};
var TAGS={"1": {"linkedin": "#Ortopedia #LCA #ChirurgiaDelGinocchio", "instagram": "#ortopedia #ginocchio #legamentocrociato #lca #collateralemediale #instabilita #chirurgiaortopedica #ortopediaticino #medicinabasatasulleprove #traumatologiadellosport", "kw": "legamento crociato anteriore, legamento collaterale mediale, instabilità rotatoria anteromediale, ricostruzione legamentosa"}};
var NLB={"1": {"prof": ["LCA più sMCL con peroneo lungo: stabilità a 2 anni in 59 pazienti, senza gruppo di controllo", "Una coorte monocentrica (J Exp Orthop, ottobre 2026) segue 59 pazienti su 63 operati di ricostruzione del LCA più ricostruzione a banda singola del collaterale mediale superficiale con lembo diviso di peroneo lungo, per instabilità rotatoria anteromediale. A 2 anni la differenza laterale del cassetto anteriore a 90° con rotazione esterna è 0,0 ± 1,3 mm (IC 95% da -0,4 a 0,3), il Lachman 1,8 ± 1,3 mm e il pivot-shift è negativo nel 93%; IKDC da 59 a 85 e Lysholm da 61 a 89 (p<0,001), ritorno a qualsiasi sport nel 66%, AOFAS mediano 100.", "Nota critica: nessun gruppo di controllo, nessuna misura strumentale preoperatoria, punteggi preoperatori raccolti a posteriori, un solo operatore, coorte mista di primari e revisioni e soglia di 3 mm non validata; l'innesto del LCA è il semitendineo nel 91% e il Lemaire c'è nel 29%, quindi non è un costrutto con quadricipite e Lemaire sistematico."], "mix": ["Crociato e legamento collaterale mediale ricostruiti insieme: ginocchio stabile a due anni", "Uno studio su 59 pazienti ha seguito per due anni chi aveva rotto il legamento crociato anteriore e aveva anche un'instabilità sul lato interno che faceva ruotare il ginocchio in modo anomalo. Oltre al crociato è stato ricostruito il legamento collaterale mediale con un tendine prelevato dalla gamba (peroneo lungo). A due anni la stabilità misurata non differiva in modo rilevante da quella del ginocchio sano, il test di rotazione era negativo nel 93% e i punteggi riferiti dai pazienti erano saliti, con una buona funzione della caviglia. Il 66% era tornato a qualche sport.", "Nota sul limite: non c'è un gruppo di confronto, i punteggi di partenza sono stati ricostruiti a posteriori e i pazienti erano molto diversi tra loro; lo studio dice che la tecnica è praticabile, non che prevalga su altre."], "paz": ["Legamento crociato e collaterale mediale: i risultati a due anni di una tecnica combinata", "In alcune lesioni del ginocchio si rompono insieme il legamento crociato anteriore e il legamento sul lato interno. In questo studio 59 persone sono state operate ricostruendo entrambi, e usando per quello interno un tendine della gamba. Dopo due anni il ginocchio operato era stabile quasi quanto l'altro e i punteggi riferiti dai pazienti erano più alti di prima; due persone hanno avuto un ritardo di guarigione della ferita alla gamba che ha richiesto una revisione. Circa due su tre erano tornate a fare sport.", "Lo studio non ha un gruppo di confronto: i risultati descrivono questa tecnica, non la paragonano ad altre. Ogni caso si discute con il chirurgo."], "kw": "legamento crociato anteriore, legamento collaterale mediale, instabilità del ginocchio, ricostruzione legamentosa"}, "2": {"prof": ["Soglie MCID e PASS dopo LCA: in nove studi variano troppo per essere importate", "Una revisione sistematica (Arthroscopy, ottobre 2026) di 9 studi sulle soglie di rilevanza clinica dopo ricostruzione del LCA riporta per l'IKDC soggettivo un MCID da 9,0 a 10,4 e un PASS da 74,2 a 86,8; per le sottoscale del KOOS l'MCID va da 2,5 a 21,9 (dolore 13,9, sintomi 5,4, attività quotidiane 5,1, sport 2,5, qualità di vita 21,9) e il PASS da 57,1 a 100,0. Le soglie dipendono da popolazione, metodo di calcolo e domanda di ancoraggio.", "Nota critica: 9 studi non randomizzati valutati con MINORS, nessuna sintesi quantitativa e intervalli di confidenza non riportati nell'abstract; gli autori concludono che le soglie vanno calcolate per coorte."], "mix": ["Quanto deve migliorare un punteggio dopo il crociato perché conti? Le soglie cambiano da studio a studio", "Una revisione di nove studi ha cercato i valori oltre i quali un miglioramento nei questionari dopo l'intervento al crociato viene considerato rilevante per il paziente, o il punteggio considerato accettabile. Per il questionario IKDC la differenza minima rilevante va da 9,0 a 10,4 punti e il livello accettabile da 74,2 a 86,8; per le singole parti del questionario KOOS i valori cambiano molto, da 2,5 a 21,9 punti per la differenza minima. Dipendono da chi è stato studiato e da come si calcolano.", "Nota sul limite: sono pochi studi, non confrontabili in modo diretto e senza una sintesi statistica; vuol dire che non esiste una soglia unica da applicare a tutti."], "paz": ["Dopo il crociato, quanto deve migliorare un questionario perché il cambiamento sia rilevante?", "Dopo un intervento al legamento crociato si usano questionari per misurare come sta il ginocchio. Una revisione di nove studi ha cercato quanta variazione di punteggio venga considerata importante per chi è stato operato, e quale punteggio sia ritenuto accettabile. I valori trovati sono molto diversi da uno studio all'altro, perché dipendono dalle persone studiate e dal modo di calcolarli.", "Per questo un singolo numero non basta a giudicare il proprio recupero: se ne parla con il chirurgo e con il fisioterapista."], "kw": "legamento crociato anteriore, questionari ginocchio, recupero dopo intervento, punteggio IKDC KOOS"}, "3": {"prof": ["Osteotomia tibiale ad apertura mediale, K-L IV: MPTA oltre 95° non peggiora gli esiti a 5 anni", "Una coorte retrospettiva (Front Surg, settembre 2026) su 165 ginocchia con gonartrosi mediale K-L IV operate di osteotomia tibiale ad apertura mediale confronta MPTA >95° (81) e ≤95° (84) a un follow-up medio di 64,5 ± 3,6 mesi. Dopo aggiustamento sul basale la differenza media di WOMAC è -0,16 (IC 95% da -5,42 a 5,11; p=0,953), di Lysholm 0,24 (da -3,22 a 3,69; p=0,893), di VAS -0,07 (da -0,39 a 0,24; p=0,645) e di mobilità -1,52° (da -4,44 a 1,39; p=0,306).", "Nota critica: l'MPTA è misurato al follow-up e non assegnato, quindi i gruppi non sono confrontabili per disegno; gli intervalli non escludono differenze di circa 5 punti di WOMAC e gli autori stessi precisano che il dato non sostiene l'ipercorrezione deliberata."], "mix": ["Osteotomia tibiale per artrosi interna avanzata: un'angolazione oltre 95° non ha peggiorato gli esiti", "Uno studio su 165 ginocchia con artrosi avanzata del lato interno, operate con osteotomia di apertura della tibia, ha confrontato chi a fine controllo aveva un angolo della tibia oltre 95° con chi era sotto questa soglia. A circa cinque anni dolore, funzione e movimento erano simili nei due gruppi: le differenze, corrette per il punto di partenza, sono piccole e con intervalli che comprendono lo zero.", "Nota sul limite: lo studio è retrospettivo e l'angolo non è stato assegnato a caso; non indica quale sia l'angolo ottimale né autorizza a correggere volutamente oltre 95°, come precisano gli stessi autori."], "paz": ["Osteotomia della tibia per artrosi avanzata: l'angolo di correzione a cinque anni", "In alcune artrosi del ginocchio si riallinea la gamba con un'osteotomia della tibia. Uno studio su 165 ginocchia ha chiesto se una correzione più ampia di una certa soglia desse risultati diversi a circa cinque anni. Dolore, funzione e movimento sono risultati simili tra chi aveva superato la soglia e chi no.", "Lo studio guarda indietro nel tempo e non stabilisce quale correzione sia giusta per ciascuno: lo decide il chirurgo sul singolo caso."], "kw": "osteotomia tibiale alta, artrosi del ginocchio, riallineamento della gamba, gonartrosi mediale"}, "4": {"prof": ["Lesione dell'arteria poplitea con multilegamentosa o frattura del piatto: 48 pazienti in 20 anni", "Una coorte retrospettiva monocentrica (J Exp Orthop, ottobre 2026) di 48 pazienti con lesione dell'arteria poplitea all'angio-TC (36 multilegamentose, 12 fratture del piatto tibiale) fra 2003 e 2023: bypass in 30 (62,5%), patch venoso in 10 (20,8%), riparazione primaria in 8 (16,7%), fissatore esterno in tutti, lesione del peroneo nel 31,3%, amputazione in 5 (10,4%), tutte nel gruppo multilegamentoso con presentazione tardiva. IKDC 85,4 contro 74,2 (p=0,032) e VAS 2,39 contro 3,47 (p=0,049) a favore delle fratture.", "Nota critica: 12 pazienti nel gruppo fratture, nessun IC per i punteggi e nessuna correzione per confronti multipli; 5 amputazioni su 36 contro 0 su 12 danno un RR 3,86 (IC 95% 0,23-65,19), un dato che non può né provare né escludere la differenza, e il follow-up non è riportato nell'abstract."], "mix": ["Ginocchio con lesione dell'arteria poplitea: le amputazioni sono arrivate dopo diagnosi e invio tardivi", "Uno studio su 48 pazienti seguiti in vent'anni in un centro di riferimento ha esaminato le lesioni dell'arteria dietro il ginocchio dopo traumi gravi, con rottura di più legamenti o con frattura. Nella maggior parte è stato fatto un bypass; cinque pazienti (10%) sono stati amputati, tutti nel gruppo con lesioni di più legamenti e dopo una diagnosi o un invio arrivati tardi. Al controllo finale funzione e dolore erano un po' peggiori nel gruppo con più legamenti rispetto a quello con frattura.", "Nota sul limite: il gruppo con frattura è di 12 persone, i confronti sono esplorativi e non si sa per quanto tempo siano stati seguiti; lo studio mostra un'associazione con il ritardo, non una causa."], "paz": ["Lesioni gravi del ginocchio con danno ai vasi: la rapidità della diagnosi conta", "Dopo traumi molto violenti del ginocchio, con rottura di più legamenti o frattura, può danneggiarsi anche l'arteria che passa dietro l'articolazione. In uno studio su 48 persone seguite in vent'anni, le amputazioni sono avvenute solo tra chi aveva rotto più legamenti ed era arrivato tardi al centro specializzato.", "Lo studio descrive l'esperienza di un solo centro e non può provare che il ritardo sia la causa."], "kw": "multilegamentosa ginocchio, lussazione del ginocchio, arteria poplitea, frattura piatto tibiale"}, "5": {"prof": ["EMG nell'atterraggio dopo LCA: 32 studi, alterazioni specifiche per compito in chi è tornato allo sport", "Una revisione sistematica con meta-analisi (KSSTA, ottobre 2026) di 32 studi (556 LCA tornati allo sport, 501 controlli sani) confronta l'attivazione muscolare in 13 compiti di atterraggio. Tre risultati a evidenza moderata: più attivazione dei flessori mediali nella fase reattiva del drop landing monopodalico (SMD 0,35; IC 95% 0,01-0,69; 5 studi; I² 0%), del grande gluteo nel drop vertical jump (0,63; 0,22-1,03; 3 studi) e inizio più precoce del retto femorale nell'hop for distance (-0,64; da -1,13 a -0,14; 3 studi; I² 19%). La maggior parte degli altri confronti non mostra differenze.", "Nota critica: ogni confronto aggrega 2-5 studi, il limite inferiore del primo intervallo è 0,01 e il tipo di innesto non è riportato nell'abstract; gli autori stessi indicano che la rilevanza clinica è da chiarire."], "mix": ["Dopo il crociato, i muscoli si attivano diversamente nell'atterraggio anche a rientro avvenuto", "Una revisione di 32 studi ha confrontato, con l'elettromiografia, l'attivazione dei muscoli durante atterraggi e salti tra 556 persone operate di crociato e già tornate allo sport e 501 persone sane. Alcune differenze sono emerse in compiti specifici su una gamba sola: più attivi i muscoli posteriori della coscia e il gluteo, più precoce l'accensione di un muscolo anteriore della coscia. Per la maggior parte degli altri muscoli e compiti non si sono viste differenze.", "Nota sul limite: ogni confronto riunisce da due a cinque studi e non si sa quale innesto sia stato usato; non è dimostrato che queste differenze abbiano conseguenze cliniche."], "paz": ["Dopo il crociato, il modo in cui i muscoli lavorano in atterraggio può restare diverso", "Una revisione di 32 studi ha misurato l'attività dei muscoli della gamba durante salti e atterraggi in persone operate al legamento crociato che erano già tornate allo sport, confrontandole con persone sane. In alcuni movimenti su una sola gamba i muscoli si attivavano in modo un po' diverso.", "Non è chiaro se queste differenze abbiano conseguenze sul rischio di nuove lesioni: servono altri studi."], "kw": "legamento crociato anteriore, ritorno allo sport, atterraggio, attivazione muscolare"}, "6": {"prof": ["Angolo patella-tendine più basso e progressione dell'artrosi femororotulea nelle revisioni del LCA", "Un caso-controllo (J Exp Orthop, ottobre 2026) su 62 ginocchia di 61 pazienti sottoposti a revisione del LCA, con RM al primo e al secondo infortunio: progressione dell'artrosi femororotulea (MOAKS) in 40 (64,5%). L'angolo patella-tendine preoperatorio era 141,9 ± 4,6° con progressione contro 144,8 ± 5,7° senza (p=0,044); OR 1,15 per grado in meno (IC 95% 1,02-1,30; p=0,022); AUC 0,66 (0,50-0,80) per l'angolo da solo e 0,79 (0,68-0,90) per il modello multivariabile, senza validazione indipendente.", "Nota critica: la differenza media è inferiore alla variazione minima rilevabile (MDC95), quindi non è interpretabile sul singolo paziente; età e tipo di innesto differiscono fra i gruppi e l'innesto non è dettagliato nell'abstract."], "mix": ["Revisione del crociato: un angolo rotuleo più basso si associa all'artrosi davanti al ginocchio", "Uno studio su 62 ginocchia operate di revisione del legamento crociato ha guardato alla risonanza se l'artrosi tra rotula e femore peggiorasse tra il primo e il secondo infortunio: è peggiorata in circa due casi su tre. Chi aveva un angolo più basso tra rotula e tendine rotuleo prima dell'intervento aveva più probabilità di peggioramento (circa il 15% in più per ogni grado), ma la differenza media tra i gruppi è di circa tre gradi.", "Nota sul limite: l'angolo da solo distingue poco chi peggiora e chi no e la differenza è inferiore all'errore di misura; non si può usare per decidere sul singolo paziente."], "paz": ["Dopo un secondo infortunio al crociato, l'artrosi dietro la rotula può peggiorare", "In uno studio su 62 ginocchia operate una seconda volta al legamento crociato, l'artrosi tra rotula e femore è peggiorata in circa due casi su tre tra le due risonanze. Una misura della posizione della rotula prima dell'intervento era un po' diversa tra chi peggiorava e chi no, ma la differenza è piccola.", "La misura non è abbastanza precisa per prevedere che cosa succederà a una singola persona."], "kw": "revisione legamento crociato, artrosi femororotulea, rotula, risonanza magnetica"}, "7": {"prof": ["Resurfacing rotuleo nella TKA: meno reinterventi nelle analisi per RR, nessuna differenza in quelle per OR", "Una umbrella review (Arthroplasty, ottobre 2026) di 14 meta-analisi (2011-2025) sul resurfacing rotuleo nella TKA primaria. Dolore anteriore: OR 1,13 (IC 95% 0,71-1,82; I² 88%) ma RR 0,75 (0,65-0,86; I² 0%). Reintervento: OR 1,44 (0,54-3,84; I² 94%) ma RR 0,59 (0,52-0,67; I² 51%). Knee Function Score MD 0,63 (da -0,42 a 1,68); Knee Society Score MD 0,92 (0,34-1,50), non riproducibile in modo coerente; nessuna differenza di mobilità.", "Nota critica: le due metriche danno risposte opposte sugli stessi dati e il titolo riporta solo quella favorevole; la sovrapposizione degli studi primari fra le 14 meta-analisi non è descritta nell'abstract e gli autori giudicano le differenze di PROM non rilevanti clinicamente."], "mix": ["Rivestire la rotula nella protesi totale: meno reinterventi in una analisi, nessun vantaggio nei punteggi", "Una revisione di 14 meta-analisi ha riunito ciò che si sa sul rivestire o no la rotula durante la protesi totale di ginocchio. A seconda del modo di calcolare, il rischio di reintervento risulta più basso con il rivestimento (rischio relativo 0,59) oppure non diverso (odds ratio 1,44 con un intervallo molto ampio, da 0,54 a 3,84); i punteggi di funzione non cambiano in modo rilevante e il dolore davanti al ginocchio è poco o per nulla influenzato.", "Nota sul limite: due modi di calcolare danno risposte diverse sugli stessi studi e non è chiaro quanti studi si ripetano nelle varie meta-analisi; la scelta resta del chirurgo, caso per caso."], "paz": ["Protesi totale di ginocchio: rivestire o no la rotula, che cosa dicono le analisi", "Durante una protesi totale di ginocchio la rotula può essere rivestita con un componente oppure lasciata com'è. Una revisione di 14 analisi precedenti trova che i punteggi di funzione e il dolore davanti al ginocchio cambiano poco; in alcune analisi i reinterventi risultano meno frequenti con il rivestimento, in altre non c'è differenza.", "I risultati dipendono dal modo di calcolare: la scelta si discute con il chirurgo."], "kw": "protesi totale di ginocchio, rotula, reintervento, dolore anteriore"}, "8": {"prof": ["Registri e TKA: l'allineamento preoperatorio aggiunge poco alla previsione di revisione, ma sposta gli HR", "Analisi con modelli di Fine-Gray annidati (CORR, ottobre 2026) su 2341 TKA primarie in 1917 pazienti (2010-2024, un centro neozelandese collegato al registro nazionale). Le variabili di registro discriminano la revisione asettica in modo modesto: C-index apparente 0,66 e 0,67, validato in croce 0,59 e 0,61. Con l'allineamento preoperatorio l'apparente sale a 0,68 e 0,69, senza miglioramento in validazione; HKA sHR 1,06 per grado (IC 95% 1,00-1,12; p=0,03) nel sottogruppo con doppia imaging (1567 procedure, 68 revisioni) e 1,04 (0,99-1,09; p=0,11) nel gruppo primario. Omettere l'allineamento sposta l'HR dello stelo tibiale del 17%.", "Nota critica: un solo centro, 68 revisioni nel sottogruppo, nessun miglioramento della discriminazione validata in croce e HKA non distinguibile dal caso nel gruppo primario; l'allineamento postoperatorio non è stato testato come predittore."], "mix": ["I registri delle protesi non raccolgono l'allineamento della gamba: quanto conta?", "Uno studio su 2341 protesi totali di ginocchio ha chiesto se, aggiungendo ai dati dei registri nazionali l'allineamento della gamba prima dell'intervento, si prevedesse meglio quali protesi sarebbero state riviste. I dati di registro da soli prevedono in modo modesto (da 0,59 a 0,61 su una scala dove 0,5 è il caso e 1 la perfezione, dopo verifica su casi nuovi) e l'allineamento aggiunge una piccola quota di informazione che però non migliora la previsione verificata; omettendolo, alcuni risultati che i registri riportano cambiano.", "Nota sul limite: un solo centro e poche revisioni; lo studio non dimostra che registrare l'allineamento cambi l'esito dei pazienti."], "paz": ["Protesi di ginocchio: i registri nazionali non raccolgono l'allineamento della gamba prima dell'intervento", "I registri nazionali delle protesi raccolgono molti dati, ma non la radiografia dell'asse della gamba prima dell'operazione. Uno studio su 2341 protesi ha visto che aggiungere questa misura migliora poco la capacità di prevedere quali protesi andranno riviste, ma può cambiare alcune conclusioni che si traggono dai registri.", "Si tratta di uno studio in un solo ospedale e non cambia ciò che è consigliabile per il singolo paziente."], "kw": "protesi totale di ginocchio, registro nazionale protesi, allineamento della gamba, revisione protesi"}};
var ARTICLES=[{n:1,mono:"m-gray",dot:"green",sec:"res",j:"J Exp Orthop",h:"LCA più sMCL con peroneo lungo: stabile a 2 anni, nessun controllo",v:"Coorte di 59 pazienti su 63 con instabilità rotatoria anteromediale operati di LCA più sMCL a banda singola: differenza laterale del cassetto anteriore in rotazione esterna 0,0 ± 1,3 mm (IC 95% da -0,4 a 0,3), Lachman 1,8 ± 1,3 mm, pivot-shift negativo nel 93%; IKDC da 59 a 85, Lysholm da 61 a 89 (p<0,001); ritorno a qualsiasi sport 66%.",ax:"Weber, Maxand, Wagner",date:"ott 2026",meta:"coorte clinica monocentrica, 59 pazienti a 2 anni (63 arruolati) · [IV]",pmid:'42836103',doi:'10.1002/jeo2.70941',journal:"Journal of experimental orthopaedics",authors:"Weber P, Maxand S, Wagner M",design:"Coorte monocentrica identificata retrospettivamente e seguita in modo prospettico con protocollo standard (6, 12 e 24 mesi): ricostruzione del LCA più ricostruzione a banda singola del collaterale mediale superficiale (sMCL) con lembo diviso di peroneo lungo, tunnel-sparing, per instabilità rotatoria anteromediale (AMRI). Endpoint primario: differenza laterale del cassetto anteriore a 90° con 15° di rotazione esterna (KT-1000), margine di non inferiorità di 3 mm dichiarato dagli autori non validato per l'AMRI. Livello IV secondo gli autori. Testo completo aperto su PMC: numeri e limiti letti nel testo, non solo nell'abstract.",pop:"63 pazienti arruolati, 59 analizzati (follow-up 94%; età media 30,0 ± 7,2 anni; 48% donne): LCA primario 30, revisione 26, re-revisione 7. Innesto del LCA: semitendineo omolaterale 51%, controlaterale 40%, tendine quadricipitale 9% (6 casi). Lemaire modificato aggiunto solo in selezionati: 18 su 63 (28,6%). Follow-up medio 26,4 ± 3,5 mesi.",results:"Cassetto anteriore AMRI-correlato: differenza laterale 0,0 ± 1,3 mm (IC 95% da -0,4 a 0,3; limite superiore unilaterale 0,3 mm; non inferiorità p<0,001). Lachman 1,8 ± 1,3 mm (IC 95% da 1,4 a 2,1; p<0,001). Valgo a 20° in RX: 0,6 ± 1,0 mm (IC 95% da 0,4 a 0,9). Pivot-shift negativo 93,2%. IKDC da 58,5 ± 20,4 a 85,4 ± 11,6 e Lysholm da 60,9 ± 24,5 a 88,5 ± 11,0 (p<0,001; punteggi preoperatori raccolti a posteriori); Tegner da 5,8 ± 1,7 a 5,2 ± 1,6 (p=0,007). Ritorno a qualsiasi sport 39/59 (66,1%). Reinterventi 5 su 59 (8,5%: 2 ciclopi, 2 revisioni di ferita al prelievo, 1 artrolisi). AOFAS caviglia mediano 100 (96,7 ± 5,1).",concl:"Gli autori: la combinazione è associata a bassa differenza laterale, stabilità soddisfacente, PROM favorevoli e bassa morbilità del sito di prelievo; tecnica tunnel-sparing ragionevole nell'AMRI.",limits:"Nessun gruppo di controllo né confronto con altre tecniche per l'AMRI; nessuna misura strumentale preoperatoria (esame in anestesia contro esame da svegli: pre e post non confrontabili) e PROM preoperatori ricostruiti a posteriori · un solo operatore e un solo esaminatore, coorte mista (primari, revisioni, re-revisioni) con sottogruppi sottopotenziati · margine di 3 mm non validato; possibile sovravincolo non misurato (rotazione non quantificata).",perte:"Il collaterale mediale lo ricostruisci con allograft o reinserisci direttamente: qui è un peroneo lungo diviso a banda singola, quindi non è il tuo costrutto. Anche il LCA non è il tuo: semitendineo nel 91%, quadricipite solo in 6 casi, e il Lemaire c'è nel 29% mentre tu lo fai sempre. Dice che una sMCL semplificata può bastare in questa selezione; non muove nessuna tensione."},
{n:2,mono:"m-gray",dot:"green",sec:"res",j:"Arthroscopy",h:"MCID e PASS dopo LCA: nove studi, soglie molto diverse",v:"Revisione sistematica di 9 studi: IKDC soggettivo, MCID da 9,0 a 10,4 e PASS da 74,2 a 86,8; KOOS, MCID da 2,5 a 21,9 (dolore 13,9, sintomi 5,4, attività quotidiane 5,1, sport 2,5, qualità di vita 21,9), PASS da 57,1 a 100,0. Dimensioni dell'effetto e intervalli di confidenza non riportati nell'abstract.",ax:"Han, Jung, Chung, Moon, Jung, Lim, Kim",date:"ott 2026",meta:"revisione sistematica, 9 studi non randomizzati · [IV]",pmid:'42834687',doi:'10.1002/arj.70512',journal:"Arthroscopy : the journal of arthroscopic & related surgery : official publication of the Arthroscopy Association of North America and the International Arthroscopy Association",authors:"Han JH, Jung M, Chung K, Moon HS, Jung SH, Lim J, Kim SH",design:"Revisione sistematica fino a luglio 2025 degli studi che riportano soglie di rilevanza clinica (MCID, PASS) con questionari validati dopo ricostruzione del LCA; qualità valutata con MINORS. Nessuna sintesi quantitativa nell'abstract. Livello IV (revisione di studi di livello II-IV) secondo gli autori. Testo completo non aperto: numeri dall'abstract.",pop:"9 studi inclusi; numero di pazienti, tipo di innesto e follow-up dei singoli studi: non riportati nell'abstract.",results:"IKDC soggettivo: MCID da 9,0 a 10,4; PASS da 74,2 a 86,8. KOOS: MCID da 2,5 a 21,9 (dolore 13,9; sintomi 5,4; attività quotidiane 5,1; sport 2,5; qualità di vita 21,9); PASS da 57,1 a 100,0 (dolore 88,9-95,8; sintomi 57,1-94,6; attività quotidiane 99,3-100,0; sport 75,0-82,5; qualità di vita 62,5-71,9). Dimensioni dell'effetto e intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori: i valori variano molto con popolazione, metodo di calcolo e tipo di domanda; quelli pubblicati non sono necessariamente applicabili ad altri studi, e vanno calcolate soglie specifiche per coorte.",limits:"Solo 9 studi non randomizzati, valutati con MINORS · nessuna sintesi quantitativa e intervalli non riportati nell'abstract · non si sa quanta della variabilità dipenda dal metodo di calcolo e quanta dai pazienti.",perte:"Utile quando leggi «miglioramento clinicamente rilevante» dopo un LCA: la soglia non è unica. Il lavoro del giorno usa 11,5 punti per l'IKDC, valore fuori dall'intervallo 9,0-10,4 di questa revisione (non è detto che quel numero nascesse da una coorte di LCA). Non muove nessuna tensione."},
{n:3,mono:"m-gray",dot:"green",sec:"res",j:"Frontiers in Surgery",h:"Osteotomia tibiale in K-L IV: MPTA oltre 95° non peggiora a 5 anni",v:"Coorte retrospettiva di 165 ginocchia K-L IV operate di osteotomia tibiale ad apertura mediale, follow-up medio 64,5 ± 3,6 mesi: con MPTA >95° (81) contro ≤95° (84), differenza media aggiustata WOMAC -0,16 (IC 95% da -5,42 a 5,11; p=0,953), Lysholm 0,24 (da -3,22 a 3,69; p=0,893), VAS -0,07 (da -0,39 a 0,24), mobilità -1,52° (da -4,44 a 1,39).",ax:"Wang, Cao, Wang, Wang, Shi, Zhang, Tan",date:"set 2026",meta:"coorte retrospettiva, 165 ginocchia (81 contro 84) · [III]",pmid:'42835286',doi:'10.3389/fsurg.2026.1946486',journal:"Frontiers in surgery",authors:"Wang Y, Cao G, Wang X, Wang P, Shi X, Zhang M, Tan H",design:"Coorte retrospettiva (Henan, Cina) su gonartrosi mediale Kellgren-Lawrence IV operata di osteotomia tibiale ad apertura mediale; i gruppi sono definiti dall'MPTA misurato al follow-up su radiografie sotto carico (>95° contro ≤95°), non assegnati. Endpoint primario WOMAC; secondari Lysholm, VAS, mobilità, parametri radiografici; analisi aggiustata sul basale (ANCOVA) e correzione di Holm. Livello di evidenza non dichiarato nell'abstract: classificato qui per disegno. Testo completo non aperto: numeri dall'abstract.",pop:"165 ginocchia con artrosi mediale K-L IV: MPTA >95° in 81, ≤95° in 84; follow-up medio 64,49 ± 3,60 mesi. Età, sesso e tipo di fissazione: non riportati nell'abstract.",results:"Differenze medie aggiustate (MPTA >95° contro ≤95°): WOMAC -0,16 (IC 95% da -5,42 a 5,11; p=0,953); Lysholm 0,24 (da -3,22 a 3,69; p=0,893); VAS -0,07 (da -0,39 a 0,24; p=0,645); mobilità -1,52° (da -4,44 a 1,39; p=0,306). Miglioramento significativo di WOMAC, Lysholm, VAS e mobilità dal basale nell'intera coorte (p<0,001). Variazioni di MPTA e HKA maggiori nel gruppo >95°, senza differenze cliniche dopo Holm.",concl:"Gli autori: un MPTA >95° non è associato a esiti peggiori a 5 anni; la soglia di 95° non va letta da sola, ma il dato non definisce un target ottimale né sostiene l'ipercorrezione deliberata.",limits:"Gruppi definiti dall'MPTA finale e non assegnati: confondimento dalla scelta della correzione · intervalli che non escludono differenze di circa 5 punti di WOMAC · solo K-L IV, solo apertura mediale, 5 anni; nessun dato su pendenza tibiale, rotula o progressione artrosica.",perte:"Fai osteotomie correttive, slope compresa: questo è un dato coronale su apertura mediale in artrosi avanzata, non tocca la pendenza. Dice che superare 95° di MPTA non ha peggiorato gli esiti clinici in questa coorte, senza dire che sia un obiettivo. Non muove nessuna tensione."},
{n:4,mono:"m-gray",dot:"green",sec:"res",j:"J Exp Orthop",h:"Lesione dell'arteria poplitea: amputazioni solo nelle multilegamentose tardive",v:"Coorte retrospettiva di 48 pazienti con lesione poplitea all'angio-TC (36 multilegamentose, 12 fratture del piatto tibiale), 2003-2023: bypass in 30 (62,5%), amputazione in 5 (10,4%), tutte nel gruppo multilegamentoso con presentazione tardiva; IKDC 85,4 contro 74,2 (p=0,032) e VAS 2,39 contro 3,47 (p=0,049) a favore delle fratture; intervalli di confidenza non riportati.",ax:"Konstantinou, Stefanou, Arnaoutoglou, Dailiana, Varitimidis, Hantes",date:"ott 2026",meta:"coorte retrospettiva monocentrica, 48 pazienti (36 contro 12) · [III]",pmid:'42836166',doi:'10.1002/jeo2.70943',journal:"Journal of experimental orthopaedics",authors:"Konstantinou E, Stefanou N, Arnaoutoglou C, Dailiana Z, Varitimidis S, Hantes M",design:"Revisione retrospettiva in un centro terziario (Larissa, Grecia), 2003-2023, di pazienti con lesione dell'arteria poplitea confermata da angio-TC associata a lesione multilegamentosa o a frattura ad alta energia del piatto tibiale; confronto fra i due gruppi con IKDC e VAS. Livello III dichiarato dagli autori. Testo completo aperto su PMC non letto: numeri dall'abstract.",pop:"48 pazienti (età media 44,1 anni; 68,7% uomini): 36 con lesione multilegamentosa e 12 con lesione vascolare da frattura. Procedure vascolari: bypass poplitea 30 (62,5%), patch venoso 10 (20,8%), riparazione primaria 8 (16,7%); fissatore esterno in tutti. Durata del follow-up: non riportata nell'abstract.",results:"Lesione del nervo peroneo 15 su 48 (31,3%). Amputazione 5 (10,4%), tutte nel gruppo multilegamentoso e associate a presentazione tardiva, compromissione dei tessuti molli e gravità del danno neurovascolare. Al follow-up finale: IKDC 85,4 contro 74,2 (p=0,032); VAS dolore 2,39 contro 3,47 (p=0,049), a favore delle fratture. Intervalli di confidenza non riportati nell'abstract. Calcolo PULSE sui conteggi grezzi (potenza.py): amputazioni 5/36 contro 0/12, RR 3,86 (IC 95% 0,23-65,19).",concl:"Gli autori: nella coorte la lesione poplitea da frattura si associa a esiti funzionali migliori di quella da multilegamentosa; tutte le amputazioni dopo ritardo di diagnosi e invio, da cui l'importanza di diagnosi tempestiva e gestione vascolare-ortopedica coordinata.",limits:"Gruppo fratture di 12 pazienti e confronti esplorativi, senza IC né correzione per confronti multipli · retrospettivo, un solo centro terziario con possibile selezione dei casi gravi · durata del follow-up non riportata; l'associazione con il ritardo non prova che sia la causa.",perte:"Multilegamentose e ginocchio lussato sono nel tuo perimetro: il messaggio pratico è il ritardo di diagnosi e di invio, non una tecnica. Non cambia la tua chirurgia legamentosa e non muove nessuna tensione."},
{n:5,mono:"m-gray",dot:"gray",sec:"res",j:"Knee Surgery, Sports Traumatology, Arthroscopy",h:"EMG nell'atterraggio dopo LCA: differenze solo in compiti specifici",v:"Meta-analisi di 32 studi (556 LCA tornati allo sport, 501 controlli): evidenza moderata per più attivazione dei flessori mediali nel drop landing monopodalico (SMD 0,35; IC 95% 0,01-0,69), del grande gluteo (0,63; 0,22-1,03) e per inizio più precoce del retto femorale nell'hop for distance (-0,64; da -1,13 a -0,14); la maggior parte degli altri confronti senza differenze.",ax:"Han, Chen, Wang, Wang, Zhang, Sun, Xue, Hua",date:"ott 2026",meta:"revisione sistematica con meta-analisi, 32 studi osservazionali · [IV]",pmid:'42837112',doi:'10.1002/ksa.70637',journal:"Knee surgery, sports traumatology, arthroscopy : official journal of the ESSKA",authors:"Han Y, Chen Y, Wang Z, Wang TYF, Zhang Y, Sun Y, Xue X, Hua Y",design:"Revisione sistematica con meta-analisi a effetti casuali (7 banche dati fino a dicembre 2025) degli studi con elettromiografia durante compiti di atterraggio, che confrontano l'arto ricostruito di pazienti dichiarati tornati allo sport con arti di controlli sani; SMD con IC 95%, risultati classificati con una scala interna di evidenza. Livello IV dichiarato dagli autori. Testo completo non aperto: numeri dall'abstract.",pop:"32 studi: 556 pazienti con LCA ricostruito, tornati allo sport, e 501 controlli sani; 13 compiti di atterraggio, 15 muscoli, 4 misure EMG; ogni confronto aggrega 2-5 studi. Tipo di innesto e tempo dall'intervento: non riportati nell'abstract.",results:"Evidenza moderata: flessori mediali più attivi nella fase reattiva del drop landing monopodalico, SMD 0,35 (IC 95% 0,01-0,69; I² 0%; 5 studi); grande gluteo più attivo nella fase reattiva del drop vertical jump, 0,63 (0,22-1,03; 3 studi); retto femorale con inizio più precoce nell'hop for distance, -0,64 (da -1,13 a -0,14; I² 19%; 3 studi). La maggior parte degli altri confronti: nessuna differenza o evidenza limitata/molto limitata.",concl:"Gli autori: chi è tornato allo sport può mostrare alterazioni di attivazione specifiche per compito, più evidenti in certi atterraggi monopodalici; servono studi prospettici e interventistici per chiarirne la rilevanza clinica.",limits:"Ogni confronto riunisce 2-5 studi; il limite inferiore del primo intervallo è 0,01 · tipo di innesto e tempo dall'intervento non riportati: non si sa se valga per il tuo innesto · EMG e atterraggi non sono esiti duri: nessun dato su re-rottura o prestazione.",perte:"Tocca il rientro allo sport senza passare dal criterio di simmetria: non dice nulla sul tuo innesto e non porta numeri su LSI o re-rottura. Sfiora T3 solo come segnale neuromuscolare; non muove nessuna tensione."},
{n:6,mono:"m-gray",dot:"gray",sec:"res",j:"J Exp Orthop",h:"Revisione del LCA: angolo patella-tendine basso e artrosi femororotulea",v:"Caso-controllo su 62 ginocchia con RM al primo e al secondo infortunio del LCA: progressione dell'artrosi femororotulea (MOAKS) in 40 (64,5%); angolo patella-tendine 141,9 ± 4,6° contro 144,8 ± 5,7° (p=0,044); OR 1,15 per grado in meno (IC 95% 1,02-1,30); AUC 0,66 (0,50-0,80) per l'angolo da solo, differenza media sotto la MDC95.",ax:"Franco, Leite, Krabb, Schmidt, Medina, Berkson, Asnis, Richardson, Matzkin, Jacobs, Lattermann",date:"ott 2026",meta:"caso-controllo retrospettivo, 62 ginocchia (40 contro 22) · [III]",pmid:'42836127',doi:'10.1002/jeo2.70931',journal:"Journal of experimental orthopaedics",authors:"Franco D, Leite CBG, Krabb N, Schmidt S, Medina G, Berkson EM, Asnis PD, Richardson LC, Matzkin EG, Jacobs C, Lattermann C",design:"Caso-controllo da banca dati (2015-2023, Brigham and Women's Hospital) su pazienti operati di revisione del LCA con RM al primo e al secondo infortunio e almeno 2 anni fra i due; progressione dell'artrosi femororotulea definita con MOAKS; regressione logistica multivariabile con ROC derivata e valutata sullo stesso gruppo, senza validazione indipendente. Livello III dichiarato dagli autori. Testo completo aperto su PMC non letto: numeri dall'abstract.",pop:"62 ginocchia di 61 pazienti (età media al primo infortunio 30,60 ± 12,30 anni; BMI 26,70 ± 4,40; intervallo medio fra gli infortuni 4,77 ± 3,04 anni); senza procedure di ripristino della cartilagine. Progressione in 40 (64,5%), nessuna progressione in 22 (35,5%). Tipo di innesto per gruppo: non riportato nell'abstract, ma differisce fra i gruppi (p=0,015).",results:"Angolo patella-tendine preoperatorio 141,9 ± 4,6° con progressione contro 144,8 ± 5,7° senza (p=0,044); al secondo infortunio 142,3 ± 4,9° contro 145,6 ± 6,6° (p=0,043). OR 1,15 per ogni grado in meno (IC 95% 1,02-1,30; p=0,022). AUC 0,66 (IC 95% 0,50-0,80) per l'angolo da solo; 0,79 (0,68-0,90) per il modello multivariabile, apparente. Età (p=0,02) e tipo di innesto (p=0,015) differiscono fra i gruppi; Insall-Salvati e sTT-TG no.",concl:"Gli autori: un angolo preoperatorio più basso è predittore indipendente di progressione MOAKS (15% di probabilità in più per grado), ma la differenza media è inferiore alla MDC95, il che limita l'interpretazione sul singolo.",limits:"62 ginocchia e solo 22 senza progressione; l'IC dell'AUC dell'angolo da solo include 0,50 · modello valutato sugli stessi dati, nessuna validazione indipendente · differenza media sotto la MDC95; innesto ed età diversi fra i gruppi, non dettagliati nell'abstract.",perte:"Riguarda la revisione del LCA e la rotula, non la tua scelta dell'innesto. Il tipo di innesto differisce fra i gruppi ma non è riportato nell'abstract: non si sa se valga per il quadricipite. Non muove nessuna tensione."},
{n:7,mono:"m-gray",dot:"gray",sec:"res",j:"Arthroplasty (London)",h:"Resurfacing rotuleo nella TKA: l'effetto sui reinterventi dipende dalla metrica",v:"Umbrella review di 14 meta-analisi (2011-2025): reintervento con resurfacing OR 1,44 (IC 95% 0,54-3,84; I² 94%) ma RR 0,59 (0,52-0,67; I² 51%); dolore anteriore OR 1,13 (0,71-1,82) ma RR 0,75 (0,65-0,86); Knee Function Score MD 0,63 (da -0,42 a 1,68), Knee Society Score MD 0,92 (0,34-1,50) non riproducibile in modo coerente.",ax:"Migliorini, Maffulli, Schäfer, Pipino, Betsch, Vaishya",date:"ott 2026",meta:"umbrella review di 14 meta-analisi, PRISMA 2020 · [II]",pmid:'42834409',doi:'10.1186/s42836-026-00438-y',journal:"Arthroplasty (London, England)",authors:"Migliorini F, Maffulli N, Schäfer L, Pipino G, Betsch M, Vaishya R",design:"Umbrella review secondo PRISMA 2020 delle meta-analisi che confrontano resurfacing e conservazione della rotula nella TKA primaria (esiti: dolore anteriore, reinterventi, mobilità, PROM); sintesi a effetti casuali a livello di meta-analisi, eterogeneità con I² e robustezza con prediction interval. Livello non dichiarato nell'abstract: classificato qui per disegno. Testo completo non aperto: numeri dall'abstract.",pop:"14 meta-analisi pubblicate fra il 2011 e il 2025; numero di studi primari, di pazienti e loro sovrapposizione: non riportati nell'abstract.",results:"Dolore anteriore: OR 1,13 (IC 95% 0,71-1,82; I² 88%), RR 0,75 (0,65-0,86; I² 0%). Reintervento: OR 1,44 (0,54-3,84; I² 94%), RR 0,59 (0,52-0,67; I² 51%). Knee Function Score MD 0,63 (da -0,42 a 1,68); Knee Society Score MD 0,92 (0,34-1,50), differenza piccola non riprodotta con coerenza. Nessuna differenza di mobilità postoperatoria.",concl:"Gli autori: il resurfacing riduce il rischio di reintervento ma non dà benefici clinicamente rilevanti nei PROM, con effetti limitati e incoerenti sul dolore anteriore.",limits:"Le due metriche danno risposte opposte sugli stessi dati e il titolo riporta solo quella favorevole · sovrapposizione degli studi primari fra le 14 meta-analisi non descritta nell'abstract · eterogeneità molto alta (I² 88-94%) nelle analisi per OR.",perte:"Non tocca il VELYS in sé: la gestione rotulea è una scelta indipendente dal robot. Dice che «meno reinterventi» vale solo con la metrica RR e che i PROM non cambiano. Non muove nessuna tensione."},
{n:8,mono:"m-gray",dot:"gray",sec:"res",j:"Clin Orthop Relat Res",h:"Registri e TKA: l'allineamento preoperatorio aggiunge poco alla previsione",v:"Analisi su 2341 TKA primarie (1917 pazienti, 2010-2024, un centro neozelandese con registro nazionale): le variabili di registro discriminano la revisione asettica in modo modesto (C-index apparente 0,66, validato in croce 0,59); l'allineamento preoperatorio sale a 0,68 apparente ma non migliora la validazione; HKA sHR 1,06 per grado (IC 95% 1,00-1,12) nel sottogruppo con doppia imaging.",ax:"Hoskins, Rosser, Gusho, Lim, Dunstall",date:"ott 2026",meta:"analisi retrospettiva con collegamento al registro, 2341 TKA · livello non riportato",pmid:'42838036',doi:'10.1097/CORR.0000000000004161',journal:"Clinical orthopaedics and related research",authors:"Hoskins W, Rosser K, Gusho C, Lim M, Dunstall K",design:"Analisi retrospettiva monocentrica (gennaio 2010 - maggio 2024) di TKA primarie collegate al registro nazionale, con radiografia preoperatoria dell'arto in carico; esito revisione asettica con modelli di Fine-Gray annidati (M1 variabili di registro, M2 complessità diagnostica, M3 allineamento) e morte come rischio competitivo; discriminazione con C-index apparente e validato in croce, analisi di sensibilità su 1567 procedure con imaging pre e postoperatoria. Livello non riportato nell'abstract letto. Testo completo non aperto: numeri dall'abstract.",pop:"2341 TKA primarie in 1917 pazienti, un centro terziario; sottogruppo con doppia imaging: 1567 procedure, 68 revisioni. Numero di revisioni nel gruppo primario: non riportato nell'estratto letto.",results:"C-index M1 (solo registro): apparente 0,66 (gruppo primario) e 0,67 (sensibilità), validato in croce 0,59 e 0,61. M3 (con allineamento): apparente 0,68 e 0,69, nessun miglioramento in validazione. Quota di informazione dovuta all'allineamento: 68% (p<0,001) nella sensibilità, 47% (p=0,02) nel primario. HKA sHR 1,06 per grado (IC 95% 1,00-1,12; p=0,03) nella sensibilità; 1,04 (0,99-1,09; p=0,11) nel primario. L'HR dello stelo tibiale cambia del 17% omettendo l'allineamento; circa 30% (primario) e 34% (sottogruppo) delle ginocchia cambia terzile di rischio.",concl:"Gli autori: le variabili di registro identificano il rischio di revisione in modo modesto; l'allineamento preoperatorio aggiunge informazione piccola ma coerente e interpretabile, e ometterlo sposta alcuni HR su cui si basano chirurghi e decisori.",limits:"Un solo centro e poche revisioni (68 nel sottogruppo) · nessun miglioramento della discriminazione validata in croce con l'allineamento, e HKA non distinguibile dal caso nel gruppo primario · l'allineamento postoperatorio non è stato testato come predittore.",perte:"Con il VELYS pianifichi sull'allineamento, e i registri non lo raccolgono: il lavoro dice che registrarlo aggiunge poca capacità predittiva verificata, ma che le stime dei registri sulle scelte chirurgiche possono spostarsi senza. Non muove nessuna tensione."}];
var SUGGQ=[{"k": "kol", "n": "Michael Wagner (Sporthopaedicum Berlin, Germania)", "w": "Berlino, Germania: ultimo autore e chirurgo operatore della coorte di oggi su LCA più sMCL (PMID 42836103; afferenza letta nei metadati PubMed: Sporthopaedicum Berlin). Corrispondenza tecnica con le tue ricostruzioni del collaterale mediale e con il LCA con tendine quadricipitale (usato nelle revisioni in cui il semitendineo mancava) più Lemaire modificato. Sostituisce J. L. Rocha de Faria (6 ottobre, nessun segnale dell'utente arrivato per farla ruotare)."}];
var BRIEF_TEXT="Oggi, mercoledì 7 ottobre, otto lavori e nessuna scheda rossa né arancione: nessun richiamo di dispositivi nuovo, nessuna ritrattazione che ti riguardi, nessun nuovo consensus o linea guida. Il lavoro del giorno è una coorte sul Journal of Experimental Orthopaedics: ricostruzione del crociato più ricostruzione a banda singola del collaterale mediale superficiale con un lembo diviso di peroneo lungo, per l'instabilità rotatoria anteromediale. Su cinquantanove pazienti seguiti due anni, la differenza fra ginocchio operato e sano nel cassetto anteriore in rotazione esterna è di zero virgola zero millimetri, con deviazione standard di uno virgola tre e intervallo di confidenza da meno zero virgola quattro a zero virgola tre; il pivot-shift è negativo nel novantatré per cento e il ritorno a qualsiasi sport è del sessantasei per cento. Non è il tuo costrutto: tu usi un allograft per il collaterale, qui l'innesto del crociato è semitendineo nel novantuno per cento dei casi e il Lemaire c'è solo nel ventinove per cento. Il limite: nessun gruppo di controllo, nessuna misura strumentale preoperatoria e punteggi di partenza raccolti a posteriori. Tra le altre schede: una revisione sistematica su Arthroscopy mostra che le soglie di cambiamento clinicamente rilevante dopo il crociato variano molto fra nove studi, con l'IKDC fra nove e dieci virgola quattro punti; una coorte di centosessantacinque osteotomie tibiali ad apertura mediale in artrosi di quarto grado non trova peggioramento con un angolo tibiale oltre novantacinque gradi, ma gli intervalli non escludono differenze; una coorte di quarantotto lesioni dell'arteria poplitea, in cui tutte e cinque le amputazioni stanno nel gruppo multilegamentoso con presentazione tardiva, su un gruppo di confronto di soli dodici pazienti; una meta-analisi sull'elettromiografia nell'atterraggio dopo il crociato; un caso-controllo sull'angolo patella-tendine nelle revisioni; una umbrella review sul resurfacing rotuleo, in cui i reinterventi dipendono dalla metrica scelta; e un'analisi su registro sull'allineamento preoperatorio nella protesi totale. Nessuna tensione si sposta.";
var BRIEF_DIALOGO=[{"chi": "A", "t": "Oggi, mercoledì 7 ottobre: otto lavori, nessuna scheda rossa né arancione, nessun richiamo nuovo e nessuna ritrattazione che ti riguardi."}, {"chi": "B", "t": "E il lavoro del giorno?"}, {"chi": "A", "t": "Una coorte sul Journal of Experimental Orthopaedics: crociato più collaterale mediale ricostruiti insieme, per l'instabilità rotatoria anteromediale. Il collaterale è stato ricostruito a banda singola con un lembo diviso di peroneo lungo, e i pazienti sono cinquantanove, seguiti due anni."}, {"chi": "B", "t": "Con che risultato?"}, {"chi": "A", "t": "Il cassetto anteriore in rotazione esterna non differisce dal ginocchio sano, zero virgola zero millimetri con deviazione standard di uno virgola tre, il pivot-shift è negativo nel novantatré per cento e due su tre sono tornati a qualche sport."}, {"chi": "B", "t": "Quindi per il tuo collaterale con allograft cambia qualcosa?"}, {"chi": "A", "t": "Non direttamente: è un altro innesto e un'altra tecnica. Anche il crociato è con semitendineo nel novantuno per cento dei casi, e il Lemaire c'è solo nel ventinove per cento, mentre tu lo fai sempre."}, {"chi": "B", "t": "E il limite?"}, {"chi": "A", "t": "Nessun gruppo di controllo, nessuna misura strumentale prima dell'intervento e punteggi di partenza ricostruiti a posteriori. Dice che la tecnica è praticabile, non che prevalga su altre."}, {"chi": "B", "t": "Fra le altre schede, qualcosa che vale la pena ricordare?"}, {"chi": "A", "t": "Una revisione su Arthroscopy: le soglie di cambiamento clinicamente rilevante dopo il crociato variano molto fra nove studi. Per l'IKDC la differenza minima va da nove a dieci virgola quattro punti."}, {"chi": "B", "t": "Esatto, gli autori stessi dicono di calcolarla per coorte. C'è poi una coorte di centosessantacinque ginocchia con artrosi avanzata operate di osteotomia: un angolo tibiale oltre novantacinque gradi non ha peggiorato gli esiti, ma gli intervalli non escludono differenze e il dato non giustifica l'ipercorrezione."}, {"chi": "A", "t": "Esatto, gli autori stessi dicono di calcolarla per coorte. C'è poi una coorte di cinquantaquattro osteotomie, anzi centosessantacinque ginocchia, con artrosi avanzata: un angolo tibiale oltre novantacinque gradi non ha peggiorato gli esiti, ma gli intervalli non escludono differenze e il dato non giustifica l'ipercorrezione."}, {"chi": "B", "t": "E sulle lesioni gravi del ginocchio?"}, {"chi": "A", "t": "Quarantotto lesioni dell'arteria poplitea: tutte e cinque le amputazioni nel gruppo multilegamentoso, tutte dopo diagnosi o invio tardivi, ma il gruppo di confronto è di soli dodici pazienti."}, {"chi": "B", "t": "Nessuna tensione si sposta oggi."}, {"chi": "A", "t": "No, nessuna."}];
